p='src/server/services/project-service.ts'
sub(p,'''import type {
  ArchiveProjectInput,
  CreateProjectInput,''','''import { issueStatusSchema } from "@/schemas/issue";
import type {
  ArchiveProjectInput,
  CloneProjectInput,
  CreateProjectInput,''')
sub(p,'''export async function updateProject(''','''/**
 * Clones a project into a new one of the same workspace (ADR 0012). Gated
 * like a creation, plus read access to the source. With `includeIssues`, every
 * live issue is copied as a fresh start (default status, unassigned, numbered
 * from 1); comments, attachments and links are never copied. Every quota is
 * checked before anything is written, and one `project.cloned` replaces the
 * `project.created` / `issue.created` announcements.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));
  assertNotArchived("Project", source.id, source);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const issuesToCopy = input.includeIssues
    ? await issueRepo.listLiveIssuesForProject(input.orgId, source.id)
    : [];
  if (
    issuesToCopy.length > 0 &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, issuesToCopy.length)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more than its issue limit per project; ` +
        `cannot copy ${issuesToCopy.length} issues from ${source.key}`,
    );
  }

  const parsedStatus = issueStatusSchema.safeParse(
    org.settings.defaultIssueStatus,
  );
  const status = parsedStatus.success ? parsedStatus.data : "backlog";

  const clone = await projectRepo.insertClonedProject(
    source,
    input.name,
    input.slug,
    input.key,
  );

  const issuesCopied =
    issuesToCopy.length > 0
      ? await issueRepo.insertIssueCopies(
          input.orgId,
          clone.id,
          issuesToCopy,
          actor.userId,
          status,
        )
      : 0;

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: clone.id,
    sourceProjectId: source.id,
    issuesCopied,
  });

  return clone;
}

export async function updateProject(''')
EOF
